UPDATE catalog_source SET adapter_key='numiscollect-html',status='probing',price_role='none',base_url='https://shop.numiscollect.eu',access_review_status='allowed',access_reviewed_at=now(),poll_interval=interval '7 days',next_poll_at=now(),last_error=NULL,notes=concat_ws(E'\n',NULLIF(notes,''),'Public product sitemaps and cards are permitted. Current and unavailable individual coins are catalog evidence. Offer prices are ignored and never stored.'),updated_at=now() WHERE source_key='numiscollect.eu';
